// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 value) public {
        // Ensure caller is not address(0) to avoid issues with blacklist checks
        vm.assume(caller != address(0));

        // Bound value to something reasonable (value starts at 1000e18, but we can use any value)
        // We'll use the default value from the contract

        // First, call XBornID() to set initial balances (owner gets totalDistributed)
        c.XBornID();

        // Now call getTokens() from the fuzzed caller
        // We need to ensure totalRemaining > 0, so skip if not
        if (c.totalRemaining() == 0) return;

        // Call getTokens()
        vm.prank(caller);
        c.getTokens();

        // The general rule: after calling getTokens(), the caller should be blacklisted
        // if they received tokens (value > 0). Since the code only calls getTokens() when
        // value > 0 (otherwise it reverts), any caller that successfully calls getTokens()
        // must be blacklisted.
        assertTrue(c.blacklist(caller));
    }
}

